import * as React from 'react'
import { FileCode, Download, PanelTop, Code, GitCompare } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { CodeBlock, type CodeLanguage } from '@/components/ui/code-block'
import { DiffViewer } from '@/components/ui/diff-viewer'
import { StreamingMarkdown } from '@/components/ui/streaming-markdown'
import { useControllableState } from '@/components/ui/util'
import { useAsyncAction, productURL } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
export interface ArtifactVersion {
  id: string
  label: string
  content: string
  createdAt?: string
}
export interface ArtifactData {
  id: string
  title: string
  kind: 'code' | 'markdown' | 'text' | 'image'
  language?: CodeLanguage
  filename?: string
  versions: ArtifactVersion[]
}
export interface ArtifactPanelProps extends React.ComponentProps<'section'> {
  artifact: ArtifactData
  versionId?: string
  onVersionChange?: (id: string) => void
  view?: 'preview' | 'source' | 'diff'
  defaultView?: 'preview' | 'source' | 'diff'
  onViewChange?: (view: 'preview' | 'source' | 'diff') => void
  onDownload?: (artifact: ArtifactData, version: ArtifactVersion) => void | Promise<void>
  renderPreview?: (artifact: ArtifactData, version: ArtifactVersion) => React.ReactNode
}
interface ArtifactContext {
  artifact: ArtifactData
  version: ArtifactVersion
  setVersion: (id: string) => void
  view: 'preview' | 'source' | 'diff'
  setView: (view: 'preview' | 'source' | 'diff') => void
  onDownload?: ArtifactPanelProps['onDownload']
  renderPreview?: ArtifactPanelProps['renderPreview']
}
const Context = React.createContext<ArtifactContext | null>(null)
const useArtifact = () => {
  const c = React.useContext(Context)
  if (!c) throw new Error('Artifact parts need ArtifactPanel.')
  return c
}
/** Versioned artifacts. Executable code remains source unless an application supplies its own preview. */
export function ArtifactPanel({
  artifact,
  versionId,
  onVersionChange,
  view,
  defaultView = 'preview',
  onViewChange,
  onDownload,
  renderPreview,
  children,
  className,
  ...props
}: ArtifactPanelProps) {
  const [selected, setSelected] = useControllableState({
      value: versionId,
      defaultValue: artifact.versions.at(-1)?.id ?? '',
      onChange: onVersionChange,
    }),
    [mode, setMode] = useControllableState({
      value: view,
      defaultValue: defaultView,
      onChange: onViewChange,
    }),
    version =
      artifact.versions.find((version) => version.id === selected) ?? artifact.versions.at(-1),
    valid =
      !!version &&
      artifact.versions.every((item) => item.id && item.label) &&
      new Set(artifact.versions.map((version) => version.id)).size === artifact.versions.length
  return (
    <section
      {...props}
      data-slot="artifact-panel"
      aria-label={artifact.title}
      className={cn('w-full min-w-0 overflow-hidden rounded-xl border bg-background', className)}
    >
      {valid && version ? (
        <Context.Provider
          value={{
            artifact,
            version,
            setVersion: setSelected,
            view:
              mode === 'diff' &&
              (artifact.kind === 'image' || artifact.versions[0]?.id === version.id)
                ? 'preview'
                : mode,
            setView: setMode,
            onDownload,
            renderPreview,
          }}
        >
          {children ?? (
            <>
              <ArtifactPanelHeader />
              <ArtifactPanelContent />
            </>
          )}
        </Context.Provider>
      ) : (
        <p role="alert" className="p-4 text-sm text-destructive">
          Artifacts need at least one version with unique IDs and labels.
        </p>
      )}
    </section>
  )
}
export function ArtifactPanelHeader() {
  const c = useArtifact(),
    action = useAsyncAction(),
    imageURL = c.artifact.kind === 'image' ? productURL(c.version.content, true) : undefined,
    openImage =
      !c.onDownload &&
      !!imageURL &&
      typeof window !== 'undefined' &&
      !/^(blob:|data:)/.test(imageURL) &&
      new URL(imageURL, window.location.href).origin !== window.location.origin
  const download = () =>
    void action.run(async () => {
      if (c.onDownload) {
        await c.onDownload(c.artifact, c.version)
        return
      }
      const image = c.artifact.kind === 'image',
        href = image
          ? productURL(c.version.content, true)
          : URL.createObjectURL(new Blob([c.version.content], { type: 'text/plain;charset=utf-8' }))
      if (!href) throw new Error('The image URL cannot be downloaded.')
      const link = document.createElement('a')
      link.href = href
      if (!openImage)
        link.download = c.artifact.filename ?? `${c.artifact.id}${image ? '.png' : '.txt'}`
      link.rel = 'noopener noreferrer'
      if (image) link.target = '_blank'
      link.click()
      if (!image) setTimeout(() => URL.revokeObjectURL(href), 0)
    })
  return (
    <header className="space-y-3 border-b p-3">
      <div className="flex flex-wrap items-center gap-2">
        <FileCode className="size-4 shrink-0 text-muted-foreground" />
        <h3 className="min-w-0 flex-1 truncate text-sm font-medium">{c.artifact.title}</h3>
        <select
          aria-label="Artifact version"
          className="h-8 max-w-40 rounded-md border bg-background px-2 text-xs"
          value={c.version.id}
          onChange={(event) => c.setVersion(event.target.value)}
        >
          {c.artifact.versions.map((version) => (
            <option key={version.id} value={version.id}>
              {version.label}
            </option>
          ))}
        </select>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={openImage ? 'Open image' : 'Download artifact'}
          disabled={action.busy}
          onClick={download}
        >
          <Download />
        </Button>
      </div>
      <div
        role="tablist"
        aria-label="Artifact view"
        className="flex flex-wrap gap-1"
        onKeyDown={(event) => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
          const options = [
              ...event.currentTarget.querySelectorAll<HTMLButtonElement>(
                '[role=tab]:not(:disabled)',
              ),
            ],
            index = options.indexOf(document.activeElement as HTMLButtonElement),
            next =
              event.key === 'Home'
                ? 0
                : event.key === 'End'
                  ? options.length - 1
                  : (index + (event.key === 'ArrowRight' ? 1 : -1) + options.length) %
                    options.length
          event.preventDefault()
          options[next]?.click()
          options[next]?.focus()
        }}
      >
        {(
          [
            { view: 'preview', label: 'Preview', Icon: PanelTop },
            { view: 'source', label: 'Source', Icon: Code },
            { view: 'diff', label: 'Changes', Icon: GitCompare },
          ] as const
        ).map(({ view, label, Icon }) => (
          <Button
            key={view}
            type="button"
            role="tab"
            aria-selected={c.view === view}
            tabIndex={c.view === view ? 0 : -1}
            variant={c.view === view ? 'secondary' : 'ghost'}
            size="sm"
            disabled={
              view === 'diff' &&
              (c.artifact.kind === 'image' || c.artifact.versions[0]?.id === c.version.id)
            }
            onClick={() => c.setView(view)}
          >
            <Icon />
            {label}
          </Button>
        ))}
      </div>
      {action.error && (
        <p role="alert" className="text-xs text-destructive">
          {action.error}
        </p>
      )}
    </header>
  )
}
export function ArtifactPanelContent() {
  const c = useArtifact(),
    index = c.artifact.versions.findIndex((version) => version.id === c.version.id),
    before = c.artifact.versions[Math.max(0, index - 1)],
    image = c.artifact.kind === 'image',
    src = image ? productURL(c.version.content, true) : undefined
  return (
    <div
      role="tabpanel"
      aria-label={`${c.view} of ${c.artifact.title}`}
      className="max-h-[40rem] min-h-40 overflow-auto p-4"
    >
      {c.view === 'diff' ? (
        image ? (
          <p className="text-xs text-muted-foreground">
            Image differences require an application renderer.
          </p>
        ) : (
          <DiffViewer
            before={before.content}
            after={c.version.content}
            beforeLabel={before.label}
            afterLabel={c.version.label}
            defaultMode="inline"
          />
        )
      ) : c.view === 'source' ? (
        <CodeBlock
          code={c.version.content}
          language={
            image
              ? 'text'
              : (c.artifact.language ?? (c.artifact.kind === 'markdown' ? 'markdown' : 'text'))
          }
          filename={c.artifact.filename}
        />
      ) : (
        (c.renderPreview?.(c.artifact, c.version) ??
        (image ? (
          src ? (
            <img
              src={src}
              alt={c.artifact.title}
              className="mx-auto max-h-96 max-w-full rounded-lg object-contain"
            />
          ) : (
            <p role="alert" className="text-xs text-destructive">
              Unsupported image URL.
            </p>
          )
        ) : c.artifact.kind === 'markdown' ? (
          <StreamingMarkdown content={c.version.content} />
        ) : c.artifact.kind === 'code' ? (
          <CodeBlock
            code={c.version.content}
            language={c.artifact.language ?? 'text'}
            filename={c.artifact.filename}
          />
        ) : (
          <div className="whitespace-pre-wrap break-words text-sm leading-relaxed">
            {c.version.content}
          </div>
        )))
      )}
    </div>
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { Check, Copy, Download, WrapText } from 'lucide-react'
import type { ThemedTokenWithVariants } from 'shiki/core'
import { Button } from '@/components/ui/button'
import { highlightCode, type CodeLanguage } from '@/components/ui/code-highlighter'
import { useControllableState } from '@/components/ui/util'
import { cn } from '@/lib/utils'

export { codeLanguages, type CodeLanguage } from '@/components/ui/code-highlighter'
export interface CodeBlockProps extends Omit<React.ComponentProps<'figure'>, 'onCopy'> {
  code: string
  language?: CodeLanguage
  filename?: string
  label?: string
  lineNumbers?: boolean
  startLine?: number
  highlightedLines?: number[]
  wrap?: boolean
  defaultWrap?: boolean
  onWrapChange?: (wrap: boolean) => void
  copyable?: boolean
  downloadable?: boolean
  maxHighlightLength?: number
  onCopy?: (code: string) => void | Promise<void>
}
interface CodeContext {
  code: string
  filename: string
  language: CodeLanguage
  lineNumbers: boolean
  startLine: number
  highlightedLines: number[]
  wrap: boolean
  setWrap: (value: boolean) => void
  copyable: boolean
  downloadable: boolean
  onCopy?: CodeBlockProps['onCopy']
  tokens: ThemedTokenWithVariants[][] | null
  status: string
  setStatus: (status: string) => void
}
const Context = React.createContext<CodeContext | null>(null)
function useCode() {
  const context = React.useContext(Context)
  if (!context) throw new Error('CodeBlock parts need CodeBlock.')
  return context
}
/** Shows source as escaped React text and lazily highlights bounded code with grammar-specific imports. */
export function CodeBlock({
  code,
  language = 'text',
  filename = '',
  label = 'Code example',
  lineNumbers = true,
  startLine = 1,
  highlightedLines = [],
  wrap,
  defaultWrap = false,
  onWrapChange,
  copyable = true,
  downloadable = false,
  maxHighlightLength = 100000,
  onCopy,
  className,
  children,
  ...props
}: CodeBlockProps) {
  const [wrapped, setWrap] = useControllableState({
      value: wrap,
      defaultValue: defaultWrap,
      onChange: onWrapChange,
    }),
    [result, setResult] = React.useState<{
      code: string
      language: CodeLanguage
      tokens: ThemedTokenWithVariants[][]
    } | null>(null),
    [status, setStatus] = React.useState('')
  React.useEffect(() => {
    let stale = false
    setStatus('')
    setResult(null)
    if (
      code.length >
      Math.min(
        500000,
        Math.max(0, Number.isFinite(maxHighlightLength) ? maxHighlightLength : 100000),
      )
    ) {
      setStatus('Syntax highlighting skipped for large content.')
      return
    }
    if (language === 'text') return
    highlightCode(code, language)
      .then((tokens) => {
        if (!stale) setResult({ code, language, tokens })
      })
      .catch(() => {
        if (!stale) setStatus('Syntax highlighting unavailable. Plain text is shown.')
      })
    return () => {
      stale = true
    }
  }, [code, language, maxHighlightLength])
  const tokens = result?.code === code && result.language === language ? result.tokens : null
  return (
    <Context.Provider
      value={{
        code,
        filename,
        language,
        lineNumbers,
        startLine: Number.isFinite(startLine) ? Math.max(1, Math.floor(startLine)) : 1,
        highlightedLines,
        wrap: wrapped,
        setWrap,
        copyable,
        downloadable,
        onCopy,
        tokens,
        status,
        setStatus,
      }}
    >
      <figure
        {...props}
        aria-label={label}
        data-slot="code-block"
        className={cn('min-w-0 overflow-hidden rounded-xl border bg-muted/20', className)}
      >
        {children ?? (
          <>
            <CodeBlockHeader />
            <CodeBlockContent />
          </>
        )}
        <p
          role="status"
          className={cn(status ? 'border-t px-4 py-2 text-xs text-muted-foreground' : 'sr-only')}
        >
          {status}
        </p>
      </figure>
    </Context.Provider>
  )
}
/** Provides independently composable filename, wrapping, copy, and local download actions. */
export function CodeBlockHeader({ className, ...props }: React.ComponentProps<'figcaption'>) {
  const c = useCode()
  const copy = async () => {
    try {
      if (c.onCopy) await c.onCopy(c.code)
      else await navigator.clipboard.writeText(c.code)
      c.setStatus('Code copied.')
    } catch {
      c.setStatus('Could not copy code.')
    }
  }
  return (
    <figcaption
      {...props}
      className={cn('flex flex-wrap items-center gap-2 border-b px-3 py-2', className)}
    >
      <span className="min-w-0 flex-1 truncate text-xs font-medium">
        {c.filename || c.language}
      </span>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label="Wrap code"
        aria-pressed={c.wrap}
        onClick={() => c.setWrap(!c.wrap)}
      >
        <WrapText className="size-4" />
      </Button>
      {c.copyable && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Copy code"
          onClick={() => void copy()}
        >
          {c.status === 'Code copied.' ? <Check className="size-4" /> : <Copy className="size-4" />}
        </Button>
      )}
      {c.downloadable && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Download code"
          onClick={() => {
            const url = URL.createObjectURL(
                new Blob([c.code], { type: 'text/plain;charset=utf-8' }),
              ),
              link = document.createElement('a')
            link.href = url
            link.download = c.filename || 'code.txt'
            link.click()
            setTimeout(() => URL.revokeObjectURL(url), 1000)
          }}
        >
          <Download className="size-4" />
        </Button>
      )}
    </figcaption>
  )
}
/** Renders line numbers separately from selectable code, with optional line emphasis and wrapping. */
export function CodeBlockContent({ className, ...props }: React.ComponentProps<'pre'>) {
  const c = useCode(),
    lines = c.code.split('\n')
  return (
    <pre
      {...props}
      dir="ltr"
      tabIndex={0}
      className={cn(
        'max-h-[36rem] overflow-auto py-4 text-left text-[13px] leading-6',
        c.wrap ? 'whitespace-pre-wrap break-words' : 'whitespace-pre',
        className,
      )}
    >
      <code className="block">
        {lines.map((line, index) => (
          <span
            key={index}
            data-line={c.startLine + index}
            className={cn(
              'flex min-h-6 px-4',
              c.highlightedLines.includes(c.startLine + index) &&
                'bg-primary/10 shadow-[inset_3px_0_0_var(--primary)]',
            )}
          >
            {c.lineNumbers && (
              <span
                aria-hidden="true"
                className="me-5 w-8 shrink-0 select-none text-right text-muted-foreground/60"
              >
                {c.startLine + index}
              </span>
            )}
            <span className="min-w-0 flex-1">
              {c.tokens?.[index]
                ? c.tokens[index].map((token, i) => (
                    <span
                      key={i}
                      className="[color:var(--code-light)] dark:[color:var(--code-dark)]"
                      style={
                        {
                          '--code-light': `color-mix(in srgb,${token.variants.light?.color ?? 'var(--foreground)'} 80%,var(--foreground))`,
                          '--code-dark': `color-mix(in srgb,${token.variants.dark?.color ?? 'var(--foreground)'} 80%,var(--foreground))`,
                          fontStyle:
                            (token.variants.light?.fontStyle ?? 0) & 1 ? 'italic' : undefined,
                          fontWeight:
                            (token.variants.light?.fontStyle ?? 0) & 2 ? 'bold' : undefined,
                        } as React.CSSProperties
                      }
                    >
                      {token.content}
                    </span>
                  ))
                : line}
            </span>
            {index < lines.length - 1 ? '\n' : null}
          </span>
        ))}
      </code>
    </pre>
  )
}

import type { HighlighterCore, ThemedTokenWithVariants } from 'shiki/core'

export const codeLanguages = [
  'text',
  'javascript',
  'jsx',
  'typescript',
  'tsx',
  'json',
  'css',
  'html',
  'markdown',
  'bash',
  'yaml',
  'sql',
  'python',
] as const
export type CodeLanguage = (typeof codeLanguages)[number]
const loaders = {
  javascript: () => import('shiki/langs/javascript.mjs'),
  jsx: () => import('shiki/langs/jsx.mjs'),
  typescript: () => import('shiki/langs/typescript.mjs'),
  tsx: () => import('shiki/langs/tsx.mjs'),
  json: () => import('shiki/langs/json.mjs'),
  css: () => import('shiki/langs/css.mjs'),
  html: () => import('shiki/langs/html.mjs'),
  markdown: () => import('shiki/langs/markdown.mjs'),
  bash: () => import('shiki/langs/bash.mjs'),
  yaml: () => import('shiki/langs/yaml.mjs'),
  sql: () => import('shiki/langs/sql.mjs'),
  python: () => import('shiki/langs/python.mjs'),
}
let highlighter: Promise<HighlighterCore> | undefined
const loading = new Map<string, Promise<void>>()
/** Loads the JavaScript regex engine, two themes, and only the requested grammar on demand. */
export async function highlightCode(
  code: string,
  language: CodeLanguage,
): Promise<ThemedTokenWithVariants[][]> {
  if (language === 'text')
    return code
      .split('\n')
      .map((content) => [{ content, offset: 0, variants: { light: {}, dark: {} } }])
  if (!codeLanguages.includes(language)) throw new Error(`Unsupported language: ${language}`)
  highlighter ??= Promise.all([
    import('shiki/core'),
    import('shiki/engine/javascript'),
    import('shiki/themes/github-light.mjs'),
    import('shiki/themes/github-dark.mjs'),
  ])
    .then(([core, engine, light, dark]) =>
      core.createHighlighterCore({
        themes: [light.default, dark.default],
        langs: [],
        engine: engine.createJavaScriptRegexEngine({ forgiving: true }),
      }),
    )
    .catch((error) => {
      highlighter = undefined
      throw error
    })
  const instance = await highlighter
  if (!loading.has(language))
    loading.set(
      language,
      loaders[language]()
        .then((grammar) => instance.loadLanguage(grammar.default))
        .catch((error) => {
          loading.delete(language)
          throw error
        }),
    )
  await loading.get(language)
  return instance.codeToTokensWithThemes(code, {
    lang: language,
    themes: { light: 'github-light', dark: 'github-dark' },
  })
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
